// A particle system feeding a GPU vertex buffer: 20000 particles, 120 frames. Each frame moves the particles and
// writes the 32-byte vertex records (position, velocity, packed colour, size, life) a WebGPU or WebGL upload takes.
// This version keeps the particles in the vertex layout itself (vertex.gen.ts, generated by the layout intrinsic
// library from gen.mjs): the simulation writes the upload buffer in place, and nothing is serialized.
// Original code, Apache-2.0.
import { VertexView, VERTEX_STRIDE } from "./vertex.gen.ts";
import { Lcg, fnv1a } from "../common/input.ts";

const N = 20000, FRAMES = 120;
const rng = new Lcg(9);
const upload = new Uint8Array(N * VERTEX_STRIDE);
const ps = new VertexView(upload, N);
for (let i = 0; i < N; i++) {
  ps.setX(i, rng.unit() * 800); ps.setY(i, rng.unit() * 600); ps.setVx(i, rng.unit() - 0.5); ps.setVy(i, rng.unit() * -2); ps.setLife(i, rng.unit() * 4);
  ps.setRgba(i, ((rng.next() & 0xffffff00) | 0xff) >>> 0); ps.setSize(i, 1 + rng.unit() * 3);
}
let h = 0;
const t0 = performance.now();
for (let f = 0; f < FRAMES; f++) {
  for (let i = 0; i < N; i++) {
    const vy = Math.fround(ps.getVy(i) + 0.05);
    ps.setVy(i, vy); ps.setX(i, ps.getX(i) + ps.getVx(i)); ps.setY(i, ps.getY(i) + vy);
    const life = Math.fround(ps.getLife(i) - 1 / 60);
    ps.setLife(i, life);
    if (life < 0 || ps.getY(i) > 600) { ps.setY(i, 0); ps.setVy(i, -2 * (i % 7) / 7); ps.setLife(i, 4); }
    ps.setSize(i, 1 + ps.getLife(i) * 0.5);
  }
  if (f % 30 === 29) h = Math.imul(h ^ fnv1a(upload), 16777619);
}
const ms = performance.now() - t0;
console.log("vertex bytes", upload.length, "frames", FRAMES, "hash", h >>> 0);
console.log(`time ${ms.toFixed(1)}`);
